describe('File Upload Test', () => {
    beforeEach(() => {
        cy.visit('https://the-internet.herokuapp.com/upload');
    });

    it('should upload a small text file and display confirmation', () => {
        const fileName = 'sample.txt';
        cy.fixture(fileName).then(fileContent => {
            cy.get('#file-upload').attachFile(fileName);
            cy.get('#file-submit').click();
            cy.get('h3').should('contain', 'File Uploaded!');
            cy.get('#uploaded-files').should('contain', fileName);
        });
    });

    it('should not upload a non-existent file and show an error', () => {
        const nonExistentFile = 'non-existent.txt';
        cy.get('#file-upload').attachFile(nonExistentFile);
        cy.get('#file-submit').click();
        cy.get('h3').should('not.exist');
        cy.get('#uploaded-files').should('not.exist');
    });
});
